/// A commitment and the prover state behind it, or the error that prevented it.
type CommitResult<F, EF, MT, L> =
    Result<(<MT as Mmcs<F>>::Commitment, WhirUniProverData<F, EF, MT, L>), WhirUniProverError>;

/// Prover state behind one WHIR-backed univariate commitment.
pub struct WhirUniProverData<F, EF, MT, L>
where
    F: TwoAdicField,
    EF: ExtensionField<F>,
    MT: Mmcs<F>,
    L: Layout<F, EF>,
{
    /// Evaluation domain each committed matrix was supplied on, in commit order.
    ///
    /// For a quotient commitment (built via
    /// `WhirUniPcs::commit_quotient_coefficient_matrices`) this holds a
    /// unit-shift placeholder coset per chunk — its `size()` is the chunk's
    /// real height, but its `shift()` is always `F::ONE`, not the chunk's
    /// actual coset shift. The univariate interface drops the real domains
    /// before that method runs, so only the height survives; callers must not
    /// read `shift()` from an entry produced this way.
    pub domains: Vec<TwoAdicMultiplicativeCoset<F>>,
    /// Coefficient matrix per committed matrix: height `2^log_height`, width
    /// equal to the matrix width, column `j` holding polynomial `j`'s
    /// coefficients in ascending degree.
    pub coeffs: Vec<RowMajorMatrix<F>>,
    /// Slot assignment of every column inside the stacked polynomial.
    pub plan: StackedPlan,
    /// Arity of the stacked polynomial.
    pub stacked_num_variables: usize,
    /// WHIR layout and Merkle prover data.
    pub whir: WhirProverData<F, EF, MT, L>,
    /// Whether this commitment is public preprocessing rather than witness data.
    ///
    /// Preprocessed matrices are padded with zeros instead of masked with
    /// randomness, so they carry no hiding budget and may be opened any number
    /// of times. The STARK prover tells us which round (if any) is the
    /// preprocessed one, and we assert that this flag agrees with the round
    /// index at opening time.
    pub preprocessed: bool,
    /// Set the first time this prover data is opened.
    ///
    /// A mask may be opened exactly once: two openings of the same mask leak the
    /// mask itself, and from the mask plus either opening the witness follows.
    /// The flag is an [`AtomicBool`] shared by clones, so forking the PCS after
    /// committing does not buy a second opening of the same masks.
    opened: Arc<AtomicBool>,
}

impl<F, EF, MT, L> WhirUniProverData<F, EF, MT, L>
where
    F: TwoAdicField,
    EF: ExtensionField<F>,
    MT: Mmcs<F>,
    L: Layout<F, EF>,
{
    /// Whether this commitment holds public preprocessing.
    pub const fn is_preprocessed(&self) -> bool {
        self.preprocessed
    }

    /// Whether this (private) commitment has already been opened.
    pub fn is_opened(&self) -> bool {
        self.opened.load(Ordering::Relaxed)
    }
}

/// Failure modes of [`WhirUniPcs`]'s prover side.
#[derive(Debug, thiserror::Error)]
pub enum WhirUniProverError {
    /// The WHIR protocol parameters were invalid for a commitment's arity.
    #[error("invalid WHIR configuration: {0}")]
    Config(#[from] WhirConfigError),
    /// A commitment would not be hidden at the size and opening shape requested.
    ///
    /// A mask of height `mask_height` hides `mask_height - 1` degrees of freedom.
    /// Opening `points` points of a `DIMENSION`-wide extension-field value leaks
    /// `points * DIMENSION` linear combinations of it, so hiding needs
    /// `mask_height > points * DIMENSION`, with margin. See Section 4.2 of
    /// <https://eprint.iacr.org/2024/1037.pdf>.
    #[error(
        "mask of height {mask_height} (width {width}, stacked arity {arity}) cannot hide against {points} opening point(s) of a degree-{extension_degree} extension field; {required} random base-field values needed, {available} available{context}"
    )]
    HidingBudgetExceeded {
        /// Height of the masked region, in rows.
        mask_height: usize,
        /// Width of the masked matrix, in base-field columns.
        width: usize,
        /// Stacked arity the schedule was read at.
        arity: usize,
        /// Number of distinct opening points over the masked region.
        points: usize,
        /// Extension-field degree, i.e. base-field values leaked per point.
        extension_degree: usize,
        /// Random base-field values the openings consume.
        required: usize,
        /// Random base-field values the mask provides.
        available: usize,
        /// The whole committed batch, for diagnosis.
        context: alloc::string::String,
    },
    /// Arithmetic overflow while sizing a hiding budget.
    #[error("hiding budget overflowed")]
    BudgetOverflow,
    /// Private prover data was opened twice.
    #[error("private hiding commitment was already opened; recommit with fresh masks")]
    AlreadyOpened,
}

/// Failure modes of [`WhirUniPcs`]'s opening check.
#[derive(Debug)]
pub enum WhirUniPcsError {
    /// The WHIR proximity argument for one commitment round rejected.
    Whir {
        /// Index of the rejecting round in commit order.
        round: usize,
        /// The underlying WHIR verifier error.
        source: p3_whir::pcs::verifier::errors::VerifierError,
    },
    /// A claimed univariate opening disagreed with the multilinear value the
    /// WHIR argument bound, once rescaled by the bridge's scale factor.
    OpeningValueMismatch {
        /// Index of the round in commit order.
        round: usize,
        /// Index of the opening batch within that round.
        batch: usize,
        /// Index of the column within that batch.
        column: usize,
    },
    /// The proof carried a different number of WHIR arguments than the verifier
    /// was given commitments.
    RoundCountMismatch {
        /// Number of commitments handed to the verifier.
        expected: usize,
        /// Number of WHIR arguments in the proof.
        actual: usize,
    },
    /// A commitment's opening points or claimed value counts did not match the
    /// shape the verifier reconstructed from the public domains.
    ShapeMismatch {
        /// Index of the round in commit order.
        round: usize,
    },
}

/// Opening proof: one WHIR argument per commitment round, in round order.
#[derive(Clone, Serialize, Deserialize)]
#[serde(bound(
    serialize = "F: Serialize, EF: Serialize, MT::Commitment: Serialize, MT::MultiProof: Serialize",
    deserialize = "F: Deserialize<'de>, EF: Deserialize<'de>, MT::Commitment: Deserialize<'de>, MT::MultiProof: Deserialize<'de>"
))]
pub struct WhirUniProof<F: Send + Sync + Clone, EF, MT: Mmcs<F>> {
    /// One WHIR argument per commitment, in the order the opening call received them.
    pub rounds: Vec<PcsProof<F, EF, MT>>,
}

/// Opening schedule and per-(matrix, point) bridge scales for one commitment.
pub(crate) struct RoundSchedule<EF> {
    /// One table spec per committed matrix, one batch per opening point.
    pub(crate) protocol: OpeningProtocol,
    /// Substituted equality points, in `protocol.iter_openings()` order.
    pub(crate) points: Vec<Point<EF>>,
    /// Bridge scale per `[matrix][point]`, consumed by the verifier's
    /// rescaling check.
    pub(crate) scales: Vec<Vec<EF>>,
    /// Arity of the stacked polynomial this commitment covers.
    pub(crate) stacked_num_variables: usize,
}

/// Builds the opening schedule for one commitment from public data only.
///
/// `shapes` gives each matrix's unpadded `(log height, width)`;
/// `points_per_matrix[m]` lists the univariate points matrix `m` is opened at.
/// Every column of a matrix is opened at every one of its points, so each
/// (matrix, point) pair becomes one batch naming all of that matrix's columns.
pub(crate) fn round_schedule<F, EF>(
    shapes: &[(usize, usize)],
    points_per_matrix: &[Vec<EF>],
    folding: usize,
) -> RoundSchedule<EF>
where
    F: TwoAdicField,
    EF: ExtensionField<F>,
{
    assert_eq!(shapes.len(), points_per_matrix.len());

    // Check all shifts/products/sums before constructing the opening
    // protocol or any selector-bearing layout state. Trusted prover callers
    // retain this infallible wrapper, while proof-facing callers perform the
    // same arithmetic check before reaching this helper.
    let stacked_num_variables = checked_stacked_num_variables(
        shapes
            .iter()
            .map(|&(log_height, width)| (padded_arity(log_height, folding), width)),
    )
    .expect("native WHIR stacked geometry must fit in usize");

    let specs: Vec<TableSpec> = shapes
        .iter()
        .zip(points_per_matrix)
        .map(|(&(log_height, width), points)| {
            let schedule: Vec<OpeningRequest> = points
                .iter()
                .map(|_| OpeningBatch::new((0..width).collect(), Vec::new()))
                .collect();
            TableSpec::new(TableShape::new(log_height, width), schedule)
        })
        .collect();
    let protocol = OpeningProtocol::new(specs).pad_to_min_num_variables(folding);

    let mut points = Vec::new();
    let mut scales = Vec::with_capacity(shapes.len());
    for (&(log_height, _width), zetas) in shapes.iter().zip(points_per_matrix) {
        let arity = padded_arity(log_height, folding).get();
        let mut row = Vec::with_capacity(zetas.len());
        for &zeta in zetas {
            let (point, scale) = univariate_eq_point(zeta, arity);
            points.push(point);
            row.push(scale);
        }
        scales.push(row);
    }

    RoundSchedule {
        protocol,
        points,
        scales,
        stacked_num_variables,
    }
}

/// WHIR behind the univariate STARK PCS interface.
///
/// Hiding randomness is drawn from `rng`, a ChaCha12 stream seeded from the OS
/// entropy source at construction. Zero knowledge holds only if that stream is
/// cryptographically secure, which is why the seed is never a caller-supplied
/// constant: a fixed mask seed leaks every secret the mask was meant to hide.
#[derive(Debug)]
pub struct WhirUniPcs<EF, F, Dft, MT, Challenger, L> {
    /// WHIR protocol parameters shared by every commitment.
    pub protocol_params: ProtocolParameters,
    /// First-round folding factor, extracted from `protocol_params`.
    folding: usize,
    /// FFT engine used to encode each committed codeword.
    pub dft: Dft,
    /// Base-field Merkle commitment scheme.
    pub mmcs: MT,
    /// Challenger prototype cloned for the commit-time root absorption that the
    /// univariate interface has no transcript for; the real absorption is done
    /// by the STARK prover and verifier.
    pub challenger_proto: Challenger,
    /// Largest committed height this instance accepts, as a log2.
    pub log_max_lde_height: usize,
    /// Masking stream. Kept behind a lock so the PCS stays `Sync` in `no_std`;
    /// held only long enough to fork a per-commitment stream, never across a
    /// WHIR commit.
    rng: Mutex<StdRng>,
    _marker: PhantomData<(EF, F, L)>,
}

impl<EF, F, Dft: Clone, MT: Clone, Challenger: Clone, L> Clone
    for WhirUniPcs<EF, F, Dft, MT, Challenger, L>
{
    /// Cloning forks the masking stream by drawing a fresh seed from the source
    /// RNG, so the clone and the original never produce the same masks.
    ///
    /// Two PCS instances that shared masks would let a verifier pair an opening
    /// from one with an opening from the other and cancel the masks out, so this
    /// must not be a plain field-wise clone of the RNG.
    fn clone(&self) -> Self {
        Self {
            protocol_params: self.protocol_params.clone(),
            folding: self.folding,
            dft: self.dft.clone(),
            mmcs: self.mmcs.clone(),
            challenger_proto: self.challenger_proto.clone(),
            log_max_lde_height: self.log_max_lde_height,
            rng: Mutex::new(StdRng::from_rng(&mut *self.rng.lock())),
            _marker: PhantomData,
        }
    }
}

impl<EF, F, Dft, MT, Challenger, L> WhirUniPcs<EF, F, Dft, MT, Challenger, L>
where
    F: TwoAdicField + PrimeField64 + Ord,
    EF: ExtensionField<F> + TwoAdicField,
    Dft: TwoAdicSubgroupDft<F> + Clone + Sync,
    MT: Mmcs<F> + Clone,
    MT::ProverData<RowMajorMatrix<F>>: Clone,
    Challenger: FieldChallenger<F>
        + GrindingChallenger<Witness = F>
        + CanSampleUniformBits<F>
        + CanObserve<MT::Commitment>
        + Clone,
    L: Layout<F, EF> + Clone,
    StandardUniform: Distribution<F>,
{
    /// Builds an instance from WHIR protocol parameters.
    ///
    /// The masking stream is seeded from the OS entropy source. There is no
    /// caller-supplied seed on purpose: a seed chosen by a caller — or a
    /// constant one — would be reproducible, and a reproducible mask leaks the
    /// witness it was added to hide.
    ///
    /// # Panics
    /// Panics unless `protocol_params.folding_factor` is
    /// [`FoldingFactor::Constant`]: the adapter derives every table's padded
    /// arity from a single first-round folding factor. Also panics if the OS
    /// entropy source is unavailable, since there is then no secure way to seed
    /// the masks.
    pub fn new(
        protocol_params: ProtocolParameters,
        dft: Dft,
        mmcs: MT,
        challenger_proto: Challenger,
        log_max_lde_height: usize,
    ) -> Self {
        let FoldingFactor::Constant(folding) = protocol_params.folding_factor else {
            panic!("WhirUniPcs requires FoldingFactor::Constant");
        };
        let rng = Self::os_rng();
        Self {
            protocol_params,
            folding,
            dft,
            mmcs,
            challenger_proto,
            log_max_lde_height,
            rng: Mutex::new(rng),
            _marker: PhantomData,
        }
    }

    /// Seeds a masking stream from the OS entropy source.
    fn os_rng() -> StdRng {
        StdRng::try_from_rng(&mut rand::rngs::SysRng)
            .expect("OS entropy source must be available to seed hiding masks")
    }

    /// Forks a private masking stream for one commitment.
    ///
    /// The lock is held only for the seed draw, so a long WHIR commit never
    /// blocks another commitment on the same PCS.
    fn fork_rng(&self) -> StdRng {
        StdRng::from_rng(&mut *self.rng.lock())
    }

    /// First-round folding factor.
    pub const fn folding(&self) -> usize {
        self.folding
    }

    /// WHIR configuration for a stacked polynomial of the given arity.
    ///
    /// # Panics
    /// Panics if the parameters are invalid for that arity.
    pub fn whir_config(&self, stacked_num_variables: usize) -> WhirConfig<EF, F, Challenger> {
        WhirConfig::new(stacked_num_variables, self.protocol_params.clone())
            .expect("WHIR parameters are valid for the committed arity")
    }

    /// Padded arities and widths of the tables a commitment stacks.
    pub fn table_shapes(&self, coeffs: &[RowMajorMatrix<F>]) -> Vec<(PaddedArity, usize)> {
        coeffs
            .iter()
            .map(|m| {
                (
                    padded_arity(log2_strict_usize(m.height()), self.folding),
                    m.width(),
                )
            })
            .collect()
    }

    /// Commits matrices already given as coefficient vectors.
    ///
    /// Column `j` of `coeffs[m]` is polynomial `j`'s coefficients in ascending
    /// degree; the commitment stacks every column as one multilinear.
    ///
    /// The committed matrices are taken as already masked, so the resulting
    /// prover data is private: it may be opened exactly once.
    pub fn commit_coefficient_matrices(
        &self,
        domains: Vec<TwoAdicMultiplicativeCoset<F>>,
        coeffs: Vec<RowMajorMatrix<F>>,
    ) -> CommitResult<F, EF, MT, L> {
        self.commit_coefficient_matrices_as(domains, coeffs, false)
    }

    /// Commits coefficient matrices, tagging the prover data as public
    /// preprocessing or as private witness data.
    ///
    /// Only the tag differs: a public commitment carries no hiding budget and
    /// may be opened repeatedly, while a private one is single-use.
    fn commit_coefficient_matrices_as(
        &self,
        domains: Vec<TwoAdicMultiplicativeCoset<F>>,
        coeffs: Vec<RowMajorMatrix<F>>,
        preprocessed: bool,
    ) -> CommitResult<F, EF, MT, L> {
        let shapes = self.table_shapes(&coeffs);
        let plan = StackedPlan::new(&shapes);
        let stacked_num_variables = plan.num_variables;

        // One table per matrix: `Table` stores one polynomial per row, so the
        // coefficient matrix is transposed into (width x height).
        let tables: Vec<Table<F>> = coeffs.iter().map(|m| Table::new(m.transpose())).collect();
        let witness = L::new_witness(tables, self.folding);
        debug_assert_eq!(witness.num_variables(), stacked_num_variables);

        let prover = WhirProver::<EF, F, Dft, MT, Challenger, L>::new(
            self.whir_config(stacked_num_variables),
            self.dft.clone(),
            self.mmcs.clone(),
        );

        // `Layout::commit` absorbs the Merkle root, but the univariate interface
        // supplies no transcript here; the STARK prover absorbs the commitment
        // itself, so this absorption is directed into a discarded clone.
        let mut sink = self.challenger_proto.clone();
        let (commitment, whir) = <WhirProver<EF, F, Dft, MT, Challenger, L> as MultilinearPcs<
            EF,
            Challenger,
        >>::commit(&prover, witness, &mut sink)
        .map_err(WhirUniProverError::Config)?;

        Ok((
            commitment,
            WhirUniProverData {
                domains,
                coeffs,
                plan,
                stacked_num_variables,
                whir,
                preprocessed,
                opened: Arc::new(AtomicBool::new(false)),
            },
        ))
    }

    /// Evaluations of committed matrix `idx` over `domain`.
    ///
    /// The commitment stores coefficients, so this zero-extends them to the
    /// requested height and runs one coset DFT at the domain's shift.
    ///
    /// # Panics
    /// Panics if `domain` is smaller than the committed matrix.
    fn evaluations_on_domain(
        &self,
        prover_data: &WhirUniProverData<F, EF, MT, L>,
        idx: usize,
        domain: TwoAdicMultiplicativeCoset<F>,
    ) -> RowMajorMatrix<F> {
        let coeffs = &prover_data.coeffs[idx];
        let width = coeffs.width();
        assert!(
            domain.size() >= coeffs.height(),
            "requested domain is smaller than the committed matrix"
        );
        let mut values = coeffs.values.clone();
        values.resize(domain.size() * width, F::ZERO);
        self.dft
            .coset_dft_batch(RowMajorMatrix::new(values, width), domain.shift())
            .to_row_major_matrix()
    }

    /// Commits the masked quotient chunk coefficient matrices.
    ///
    /// The univariate interface drops the domains between producing these
    /// matrices and committing them; the commitment needs only each matrix's
    /// height, so a unit-shift coset of that height stands in for the domain.
    ///
    /// The chunk polynomials arrive already masked by
    /// [`Self::get_quotient_ldes`], which is where their hiding is bought;
    /// nothing here adds randomness, and the pooled budget was checked there.
    fn commit_quotient_coefficient_matrices(
        &self,
        coeffs: Vec<RowMajorMatrix<F>>,
    ) -> CommitResult<F, EF, MT, L> {
        let domains = coeffs
            .iter()
            .map(|m| {
                TwoAdicMultiplicativeCoset::new(F::ONE, log2_strict_usize(m.height()))
                    .expect("chunk height is within the field's two-adicity")
            })
            .collect();
        self.commit_coefficient_matrices(domains, coeffs)
    }

    /// Opens every commitment at its points, one WHIR argument per commitment.
    ///
    /// The reported values are the true univariate evaluations; each WHIR
    /// argument binds the corresponding multilinear value, which rescales to
    /// them by the bridge's scale factor.
    #[allow(clippy::type_complexity)]
    fn open_rounds(
        &self,
        rounds: Vec<(&WhirUniProverData<F, EF, MT, L>, Vec<Vec<EF>>)>,
        challenger: &mut Challenger,
    ) -> Result<(OpenedValues<EF>, WhirUniProof<F, EF, MT>), WhirConfigError> {
        let mut opened = Vec::with_capacity(rounds.len());
        let mut proofs = Vec::with_capacity(rounds.len());

        for (data, points_per_matrix) in rounds {
            let shapes: Vec<(usize, usize)> = data
                .coeffs
                .iter()
                .map(|m| (log2_strict_usize(m.height()), m.width()))
                .collect();
            let schedule = round_schedule::<F, EF>(&shapes, &points_per_matrix, self.folding);
            debug_assert_eq!(schedule.stacked_num_variables, data.stacked_num_variables);

            let prover = WhirProver::<EF, F, Dft, MT, Challenger, L>::new(
                self.whir_config(data.stacked_num_variables),
                self.dft.clone(),
                self.mmcs.clone(),
            );
            let proof = prover.open_at(
                data.whir.clone(),
                &schedule.protocol,
                &schedule.points,
                challenger,
            )?;

            let mut round_values = Vec::with_capacity(data.coeffs.len());
            for (m, zetas) in points_per_matrix.iter().enumerate() {
                let coeffs = &data.coeffs[m];
                let width = coeffs.width();
                let mut matrix_values = Vec::with_capacity(zetas.len());
                for &zeta in zetas {
                    let point_values: Vec<EF> = (0..width)
                        .map(|col| {
                            (0..coeffs.height()).rev().fold(EF::ZERO, |acc, i| {
                                acc * zeta + coeffs.values[i * width + col]
                            })
                        })
                        .collect();
                    matrix_values.push(point_values);
                }
                round_values.push(matrix_values);
            }
            opened.push(round_values);
            proofs.push(proof);
        }

        Ok((opened, WhirUniProof { rounds: proofs }))
    }

    /// Verifies every commitment's WHIR argument and the claimed evaluations.
    ///
    /// Each round rebuilds the same opening schedule the prover used from
    /// public data, replays the WHIR argument through
    /// [`PrescribedPointPcs::verify_at`] — which deliberately does not absorb
    /// the commitment, the STARK verifier having already done so — and then
    /// rescales the bound multilinear values into univariate ones and compares
    /// them against the claims.
    ///
    /// # Precondition
    ///
    /// `commitments` must carry, per matrix and in commit order, the
    /// `(log height, width)` that was actually committed: the height from
    /// each `domain`'s `log_size()` and the width implied by the opening
    /// values' lengths. This function does not authenticate those shapes
    /// against `commitment` itself — the WHIR Merkle root only pins the
    /// *stacked* arity, and distinct per-matrix shape vectors can pad to the
    /// same stacked arity — so it only checks that the WHIR argument is
    /// internally consistent with whatever shapes it is given. Callers must
    /// independently establish that the supplied shapes match what was
    /// committed; `p3_uni_stark::verify` satisfies this by fixing widths from
    /// the AIR and reconstructing domains before calling into this PCS.
    #[allow(clippy::type_complexity)]
    fn verify_rounds(
        &self,
        commitments: Vec<(
            MT::Commitment,
            Vec<(TwoAdicMultiplicativeCoset<F>, Vec<(EF, Vec<EF>)>)>,
        )>,
        proof: &WhirUniProof<F, EF, MT>,
        challenger: &mut Challenger,
    ) -> Result<(), WhirUniPcsError> {
        if proof.rounds.len() != commitments.len() {
            return Err(WhirUniPcsError::RoundCountMismatch {
                expected: commitments.len(),
                actual: proof.rounds.len(),
            });
        }

        // Validate the complete statement/proof vector before the challenger
        // or any native verifier sees the first argument. A malformed later
        // commitment must not cause earlier transcript or MMCS work.
        for (round, ((_commitment, matrices), round_proof)) in
            commitments.iter().zip(&proof.rounds).enumerate()
        {
            let mut shapes = Vec::with_capacity(matrices.len());
            let mut context_shapes = Vec::with_capacity(matrices.len());
            for (domain, openings) in matrices {
                let width = openings
                    .first()
                    .map(|(_, values)| values.len())
                    .ok_or(WhirUniPcsError::ShapeMismatch { round })?;
                if openings.iter().any(|(_, values)| values.len() != width) {
                    return Err(WhirUniPcsError::ShapeMismatch { round });
                }
                shapes.push((domain.log_size(), width));
                context_shapes.push((domain.log_size(), width, openings.len()));
            }
            let stacked_num_variables = checked_stacked_num_variables(
                shapes
                    .iter()
                    .map(|&(log_height, width)| (padded_arity(log_height, self.folding), width)),
            )
            .map_err(|_| WhirUniPcsError::ShapeMismatch { round })?;
            validate_round_config_inputs(stacked_num_variables, &self.protocol_params)
                .map_err(|_| WhirUniPcsError::ShapeMismatch { round })?;
            let config = WhirConfig::<EF, F, Challenger>::new(
                stacked_num_variables,
                self.protocol_params.clone(),
            )
            .map_err(|_| WhirUniPcsError::ShapeMismatch { round })?;
            validate_whir_pcs_context::<F, EF, MT>(
                round_proof,
                &WhirContextParams::from_native(&config),
                &context_shapes,
            )
            .map_err(|_| WhirUniPcsError::ShapeMismatch { round })?;
        }

        for (round, ((commitment, matrices), round_proof)) in
            commitments.into_iter().zip(&proof.rounds).enumerate()
        {
            let mut shapes = Vec::with_capacity(matrices.len());
            let mut points_per_matrix = Vec::with_capacity(matrices.len());
            for (domain, openings) in &matrices {
                let width = openings
                    .first()
                    .map(|(_, values)| values.len())
                    .ok_or(WhirUniPcsError::ShapeMismatch { round })?;
                if openings.iter().any(|(_, values)| values.len() != width) {
                    return Err(WhirUniPcsError::ShapeMismatch { round });
                }
                shapes.push((domain.log_size(), width));
                points_per_matrix.push(openings.iter().map(|&(z, _)| z).collect::<Vec<EF>>());
            }

            let stacked_num_variables = checked_stacked_num_variables(
                shapes
                    .iter()
                    .map(|&(log_height, width)| (padded_arity(log_height, self.folding), width)),
            )
            .map_err(|_| WhirUniPcsError::ShapeMismatch { round })?;
            let config = WhirConfig::<EF, F, Challenger>::new(
                stacked_num_variables,
                self.protocol_params.clone(),
            )
            .map_err(|_| WhirUniPcsError::ShapeMismatch { round })?;
            let schedule = round_schedule::<F, EF>(&shapes, &points_per_matrix, self.folding);
            let prover = WhirProver::<EF, F, Dft, MT, Challenger, L>::new(
                config,
                self.dft.clone(),
                self.mmcs.clone(),
            );
            let evals = prover
                .verify_at(
                    &commitment,
                    round_proof,
                    &schedule.protocol,
                    &schedule.points,
                    challenger,
                )
                .map_err(|source| WhirUniPcsError::Whir { round, source })?;

            // `evals` follows `protocol.iter_openings()` order: matrix-major,
            // then point, matching how the schedule laid out its scales.
            let mut batch = 0usize;
            for (m, (_domain, openings)) in matrices.iter().enumerate() {
                for (p, (_zeta, claimed)) in openings.iter().enumerate() {
                    let scale = schedule.scales[m][p];
                    let bound = evals
                        .get(batch)
                        .ok_or(WhirUniPcsError::ShapeMismatch { round })?;
                    if bound.current().len() != claimed.len() {
                        return Err(WhirUniPcsError::ShapeMismatch { round });
                    }
                    for (column, (&bound_value, &claimed_value)) in
                        bound.current().iter().zip(claimed).enumerate()
                    {
                        if bound_value * scale != claimed_value {
                            return Err(WhirUniPcsError::OpeningValueMismatch {
                                round,
                                batch,
                                column,
                            });
                        }
                    }
                    batch += 1;
                }
            }
        }

        Ok(())
    }
}

impl<EF, F, Dft, MT, Challenger, L> p3_commit::Pcs<EF, Challenger>
    for WhirUniPcs<EF, F, Dft, MT, Challenger, L>
where
    F: TwoAdicField + PrimeField64 + Ord,
    EF: ExtensionField<F> + TwoAdicField,
    Dft: TwoAdicSubgroupDft<F> + Clone + Sync,
    MT: Mmcs<F> + Clone,
    MT::ProverData<RowMajorMatrix<F>>: Clone,
    MT::Commitment: Serialize + for<'de> Deserialize<'de>,
    MT::MultiProof: Serialize + for<'de> Deserialize<'de>,
    Challenger: FieldChallenger<F>
        + GrindingChallenger<Witness = F>
        + CanSampleUniformBits<F>
        + CanObserve<MT::Commitment>
        + Clone,
    L: Layout<F, EF> + Clone,
    StandardUniform: Distribution<F>,
{
    type Domain = TwoAdicMultiplicativeCoset<F>;
    type Commitment = MT::Commitment;
    type ProverData = WhirUniProverData<F, EF, MT, L>;
    type Proof = WhirUniProof<F, EF, MT>;
    type Error = WhirUniPcsError;
    type ProverError = WhirUniProverError;

    fn natural_domain_for_degree(&self, degree: usize) -> Self::Domain {
        TwoAdicMultiplicativeCoset::new(F::ONE, log2_strict_usize(degree))
            .expect("degree is within the field's two-adicity")
    }

    fn commit(
        &self,
        evaluations: impl IntoIterator<Item = (Self::Domain, RowMajorMatrix<F>)>,
    ) -> Result<(Self::Commitment, Self::ProverData), Self::ProverError> {
        // ZK is on, so every trace commitment here is a masked one. The STARK
        // prover hands us an `N x w` matrix together with the *doubled* domain
        // `2N` it declared for the randomized trace, and expects the PCS to do
        // the widening.
        //
        // The widening keeps the width and doubles the height: the real rows go
        // on the even indices, random field elements on the odd ones. Because
        // the even indices are the coset generated by `g_N = g_{2N}^2`, the
        // interpolated `T'` agrees with the real trace on all of `H_N`, so the
        // AIR still vanishes there and the quotient stays a polynomial. On the
        // doubled coset — where the quotient domain lives — `T'` is random.
        //
        // `with_random_cols` then a narrowed width is how the interleave is
        // spelled: appending `w` random columns makes the buffer `2N * w` long,
        // and reinterpreting it at width `w` puts the randoms between the real
        // rows rather than after them.
        let evaluations: Vec<_> = evaluations.into_iter().collect();
        let mats: Vec<RowMajorMatrix<F>> = evaluations.iter().map(|(_, m)| m.clone()).collect();
        // The mask's random subspace must dominate everything the proof will
        // reveal about this commitment: the out-of-domain openings plus every
        // WHIR query against the folded codeword. The arity is read on the
        // doubled height, since that is what actually gets committed.
        let arity = self.stacked_arity_of(&mats, 1);
        let margin = self.query_margin(arity);
        // Hiding is a property of the single stacked polynomial this batch
        // commits, not of any one matrix: every opening the proof makes is one
        // linear constraint on that polynomial's coefficients, and the random
        // rows injected across the whole batch are what answers them. So the
        // budget is pooled over the batch — a small matrix riding along in a
        // large one is hidden by the batch's randomness, and a batch that is
        // too small overall is rejected however it is shaped.
        //
        // The interleave makes half of each doubled matrix random, so the
        // random cell count is the *original* height times the width.
        let random_cells: usize = mats
            .iter()
            .map(|m| {
                m.height()
                    .checked_mul(m.width())
                    .ok_or(WhirUniProverError::BudgetOverflow)
            })
            .sum::<Result<_, _>>()?;
        self.check_hiding_budget(random_cells, 2, margin, arity, batch_shapes(&mats))?;
        let mut rng = self.fork_rng();
        let mut domains = Vec::new();
        let mut coeffs = Vec::new();
        for (domain, mat) in evaluations {
            let width = mat.width();
            let masked = {
                let mut m = mat.with_random_cols(width, &mut rng);
                m.width = width;
                m
            };
            debug_assert_eq!(masked.height(), domain.size());
            coeffs.push(self.dft.coset_idft_batch(masked, domain.shift()));
            domains.push(domain);
        }
        self.commit_coefficient_matrices(domains, coeffs)
    }

    fn open(
        &self,
        commitment_data_with_opening_points: Vec<
            p3_commit::OpeningRequest<'_, Self::ProverData, EF>,
        >,
        fiat_shamir_challenger: &mut Challenger,
    ) -> Result<(p3_commit::OpenedValues<EF>, Self::Proof), Self::ProverError> {
        let rounds = commitment_data_with_opening_points
            .into_iter()
            .map(|request| (request.prover_data, request.points))
            .collect();
        self.open_rounds(rounds, fiat_shamir_challenger)
            .map_err(WhirUniProverError::Config)
    }

    fn verify(
        &self,
        commitments_with_opening_points: Vec<CommitmentOpening<EF, Self::Commitment, Self::Domain>>,
        proof: &Self::Proof,
        fiat_shamir_challenger: &mut Challenger,
    ) -> Result<(), Self::Error> {
        let rounds = commitments_with_opening_points
            .into_iter()
            .map(|claim| {
                (
                    claim.commitment,
                    claim
                        .matrices
                        .into_iter()
                        .map(|matrix| {
                            (
                                matrix.domain,
                                matrix
                                    .points
                                    .into_iter()
                                    .map(|point| (point.point, point.values))
                                    .collect(),
                            )
                        })
                        .collect(),
                )
            })
            .collect();
        self.verify_rounds(rounds, proof, fiat_shamir_challenger)
    }
}

impl<EF, F, Dft, MT, Challenger, L> p3_commit::UnivariateStarkPcs<EF, Challenger>
    for WhirUniPcs<EF, F, Dft, MT, Challenger, L>
where
    F: TwoAdicField + PrimeField64 + Ord,
    EF: ExtensionField<F> + TwoAdicField,
    Dft: TwoAdicSubgroupDft<F> + Clone + Sync,
    MT: Mmcs<F> + Clone,
    MT::ProverData<RowMajorMatrix<F>>: Clone,
    MT::Commitment: Serialize + for<'de> Deserialize<'de>,
    MT::MultiProof: Serialize + for<'de> Deserialize<'de>,
    Challenger: FieldChallenger<F>
        + GrindingChallenger<Witness = F>
        + CanSampleUniformBits<F>
        + CanObserve<MT::Commitment>
        + Clone,
    L: Layout<F, EF> + Clone,
    StandardUniform: Distribution<F>,
{
    type EvaluationsOnDomain<'a> = RowMajorMatrix<F>;

    const ZK: bool = true;

    fn log_max_trace_height(&self) -> usize {
        self.log_max_lde_height
    }

    fn log_min_trace_height(&self) -> usize {
        // Multiplicative coset selectors are defined down to a single row.
        0
    }

    fn get_evaluations_on_domain<'a>(
        &self,
        prover_data: &'a Self::ProverData,
        idx: usize,
        domain: Self::Domain,
    ) -> Self::EvaluationsOnDomain<'a> {
        self.evaluations_on_domain(prover_data, idx, domain)
    }

    /// Public preprocessing commitment: zero-padded, not masked.
    ///
    /// Preprocessed columns are public by definition, so there is nothing to
    /// hide and no single-use budget to enforce. The padding matches the trace's
    /// doubled height so both live on the same domain, but the added rows are
    /// zeros rather than randomness.
    fn commit_preprocessing(
        &self,
        evaluations: impl IntoIterator<Item = (Self::Domain, RowMajorMatrix<F>)>,
    ) -> Result<(Self::Commitment, Self::ProverData), Self::ProverError> {
        let mut domains = Vec::new();
        let mut coeffs = Vec::new();
        for (domain, mat) in evaluations {
            let width = mat.width();
            let padded = {
                let mut m = mat.with_zero_cols(width);
                m.width = width;
                m
            };
            debug_assert_eq!(padded.height(), domain.size());
            coeffs.push(self.dft.coset_idft_batch(padded, domain.shift()));
            domains.push(domain);
        }
        self.commit_coefficient_matrices_as(domains, coeffs, true)
    }

    /// Commits the randomization polynomial `R` that masks the out-of-domain
    /// opening.
    ///
    /// One `2N x DIMENSION` matrix of uniform base-field randomness per
    /// requested domain, so the round opens exactly `DIMENSION` values per
    /// instance at the single out-of-domain point — the shape both uni-stark
    /// (`opened_values[0][0][0]`) and batch-stark (`opened_values[0][i][0]`)
    /// index into.
    ///
    /// Committed through the coefficient path directly rather than through
    /// [`Pcs::commit`], which would interleave the matrix a second time.
    fn get_opt_randomization_poly_commitment(
        &self,
        domains: impl IntoIterator<Item = Self::Domain>,
    ) -> Result<Option<(Self::Commitment, Self::ProverData)>, Self::ProverError> {
        let domains: Vec<_> = domains.into_iter().collect();
        let probe: Vec<RowMajorMatrix<F>> = domains
            .iter()
            .map(|d| RowMajorMatrix::new(vec![F::ZERO; d.size()], 1))
            .collect();
        let arity = self.stacked_arity_of(&probe, 0);
        let margin = self.query_margin(arity);
        let context = domain_shapes(&domains.iter().map(|d| d.size()).collect::<Vec<_>>());
        // One stacked polynomial covers every instance's R matrix, so the
        // randomness that answers this round's openings is pooled over all of
        // them. Checking per-instance would reject a small instance that is in
        // fact hidden by the batch it is committed with.
        let random_cells: usize = domains
            .iter()
            .map(|d| {
                d.size()
                    .checked_mul(EF::DIMENSION)
                    .ok_or(WhirUniProverError::BudgetOverflow)
            })
            .sum::<Result<_, _>>()?;
        self.check_hiding_budget(random_cells, 1, margin, arity, context)?;
        let mut rng = self.fork_rng();
        let coeffs: Vec<RowMajorMatrix<F>> = domains
            .iter()
            .map(|domain| {
                Ok(RowMajorMatrix::new(
                    (0..domain.size() * EF::DIMENSION)
                        .map(|_| rng.random())
                        .collect(),
                    EF::DIMENSION,
                ))
            })
            .collect::<Result<_, WhirUniProverError>>()?;
        Ok(Some(self.commit_coefficient_matrices(domains, coeffs)?))
    }

    /// Masked quotient chunk coefficients.
    ///
    /// Each chunk `q_i` on its real sub-coset `D_i` becomes
    /// `q_i + Z_{D_i} * T_i` for a random `T_i` of degree `< h`. The verifier
    /// recomposes the chunks with Lagrange selectors `L_i` satisfying
    /// `L_i(X) * Z_{D_i}(X) = cis_i * P(X)` where `P = prod_j Z_{D_j}` and
    /// `cis_i = 1 / prod_{j != i} Z_{D_j}(first_i)`, so the recomposed value
    /// becomes `Q + P * sum_i cis_i T_i`. Forcing
    /// `T_last = -sum_{j != last} (cis_j / cis_last) * T_j` makes that extra
    /// term vanish identically: the recomposed quotient is unchanged, while
    /// every individually opened chunk value is uniform random.
    ///
    /// The mask is applied in this adapter's own coefficient convention — the
    /// chunk is interpolated at its natural coset shift, so `Z_{D_i}` is
    /// `X^h - sigma_i^h` with no `GENERATOR` re-basing — which is why the
    /// compensation constants are the plain `cis` ratios.
    fn get_quotient_ldes(
        &self,
        evaluations: impl IntoIterator<Item = (Self::Domain, RowMajorMatrix<F>)>,
        num_chunks: usize,
    ) -> Result<Vec<RowMajorMatrix<F>>, Self::ProverError> {
        assert!(
            num_chunks > 1,
            "num_chunks must be > 1 to preserve hiding (got {num_chunks})"
        );
        let (domains, evaluations): (Vec<_>, Vec<_>) = evaluations.into_iter().unzip();
        let h = evaluations[0].height();
        let w = evaluations[0].width();
        // Chunks are committed at twice their real height, so the schedule is
        // read one arity up.
        // The quotient chunks are opened at the single out-of-domain point, and
        // the recomposed value at that point is public: the verifier derives it
        // from the AIR constraint evaluation and the public inputs. What has to
        // stay hidden is therefore not the recomposition but each individual
        // chunk's value, which the mask randomises while the last chunk's
        // compensation keeps the sum exact.
        //
        // The hiding itself is inherited from the trace mask, not bought here:
        // the quotient polynomial is computed *from the masked trace*, so its
        // coefficients off the real domain are already random, and the batch's
        // pooled trace randomness was checked when the trace was committed.
        // What this call must guarantee is only that each opened chunk value
        // carries at least one fresh random coefficient per extension-field
        // coordinate, so no chunk is revealed bare.
        let _ = self.stacked_arity_of(&evaluations, 1);
        if h.checked_mul(w).ok_or(WhirUniProverError::BudgetOverflow)? < EF::DIMENSION {
            return Err(WhirUniProverError::HidingBudgetExceeded {
                mask_height: h,
                width: w,
                arity: 0,
                points: 1,
                extension_degree: EF::DIMENSION,
                required: EF::DIMENSION,
                available: h * w,
                context: batch_shapes(&evaluations),
            });
        }

        let cis = zp_cis(&domains);
        let last = num_chunks - 1;
        // The recomposition identity is `q = sum_i L_i q_i` with
        // `L_i = c_i * prod_{j != i} v_j`, where `v_j` is the domain's
        // NORMALIZED vanishing polynomial. In this codebase that is
        // `v_j(X) = (X / sigma_j)^h - 1` (see `vanishing_poly_at_point`),
        // NOT the unnormalized `X^h - sigma_j^h`. The two differ by the
        // constant factor `sigma_j^h`:
        //
        //     X^h - sigma_j^h = sigma_j^h * v_j(X).
        //
        // The mask is applied in the unnormalized form below, so the mask
        // polynomial that actually enters the identity is
        // `t_i = sigma_i^h * T_i`, not `T_i`. The paper's cancellation
        // condition (eq. 14 of https://eprint.iacr.org/2024/1037) is
        // `sum_i c_i t_i = 0`, i.e.
        //
        //     sum_i c_i * sigma_i^h * T_i = 0,
        //
        // so the compensation weights must carry the `sigma^h` ratio.
        // Dropping it leaves a residual `P(X) * sum_i c_i sigma_i^h T_i` in
        // the recomposed quotient, which the verifier sees as an OOD mismatch.
        let sigma_h: Vec<F> = domains
            .iter()
            .map(|d| d.shift().exp_u64(h as u64))
            .collect();
        let last_ci_inv = cis[last].inverse();
        let scale_inv = sigma_h[last].try_inverse().expect("chunk shift is nonzero");
        let mul_coeffs: Vec<F> = (0..last)
            .map(|i| cis[i] * last_ci_inv * sigma_h[i] * scale_inv)
            .collect();

        let mut rng = self.fork_rng();
        // Random mask polynomials for every chunk but the last; the last chunk's
        // mask is the negated weighted sum that cancels the rest.
        let mut masks: Vec<Vec<F>> = (0..last)
            .map(|_| (0..h * w).map(|_| rng.random()).collect())
            .collect();
        let mut last_mask = vec![F::ZERO; h * w];
        for (j, &mul) in mul_coeffs.iter().enumerate() {
            for k in 0..h * w {
                last_mask[k] -= masks[j][k] * mul;
            }
        }
        masks.push(last_mask);

        Ok(domains
            .iter()
            .zip(evaluations)
            .enumerate()
            .map(|(i, (domain, evals))| {
                // The chunk interpolates to `h` coefficients, but the mask term
                // `Z_{D_i} * T_i` has degree `< 2h`, so the coefficient buffer
                // is widened before the upper half is written.
                let mut coeffs = self.dft.coset_idft_batch(evals, domain.shift()).values;
                coeffs.resize(2 * h * w, F::ZERO);
                // `Z_{D_i} = X^h - sigma_i^h`, so subtracting `Z_{D_i} * T_i`
                // puts `T_i`'s coefficients in the upper half and their
                // `sigma_i^h` multiples in the lower half.
                let sigma_h = domain.shift().exp_u64(h as u64);
                let mask = &masks[i];
                for k in 0..h {
                    for c in 0..w {
                        let t = mask[k * w + c];
                        coeffs[k * w + c] -= t * sigma_h;
                        coeffs[(h + k) * w + c] += t;
                    }
                }
                RowMajorMatrix::new(coeffs, w)
            })
            .collect())
    }

    /// Commits already-masked quotient chunk LDEs.
    ///
    /// Deliberately adds **no** randomness: these matrices were masked by
    /// [`Self::get_quotient_ldes`], and recommitting a copy of a masked LDE
    /// does not refresh its hiding budget — masking twice would let two
    /// openings of the same mask be paired and the mask cancelled. The
    /// commitment goes through the coefficient path directly, never through
    /// [`Pcs::commit`], so no second interleave is applied.
    fn commit_ldes(
        &self,
        ldes: Vec<RowMajorMatrix<F>>,
    ) -> Result<(Self::Commitment, Self::ProverData), Self::ProverError> {
        self.commit_quotient_coefficient_matrices(ldes)
    }

    /// Opens the hiding rounds, enforcing the single-use rule on private data.
    ///
    /// The width-preserving interleave leaves no random tail to strip from the
    /// opened values, so this override exists for the two invariants the trait
    /// default cannot provide: the preprocessed round must be the one tagged
    /// public, and a private commitment must not be opened twice.
    fn open_with_preprocessing(
        &self,
        rounds: Vec<p3_commit::OpeningRequest<'_, Self::ProverData, EF>>,
        challenger: &mut Challenger,
        preprocessed_commitment: Option<usize>,
    ) -> Result<(OpenedValues<EF>, Self::Proof), Self::ProverError> {
        for (round_idx, round) in rounds.iter().enumerate() {
            let is_preprocessed_round = preprocessed_commitment == Some(round_idx);
            assert_eq!(
                round.prover_data.preprocessed, is_preprocessed_round,
                "round {round_idx} preprocessing flag disagrees with the opening layout"
            );
            if !round.prover_data.preprocessed
                && round.prover_data.opened.swap(true, Ordering::Relaxed)
            {
                return Err(WhirUniProverError::AlreadyOpened);
            }
        }
        let plain = rounds
            .into_iter()
            .map(|request| (request.prover_data, request.points))
            .collect();
        self.open_rounds(plain, challenger)
            .map_err(WhirUniProverError::Config)
    }

    /// Verifies a hiding proof.
    ///
    /// Nothing is re-joined here: the interleave preserves width, so the opened
    /// values the prover reports are already the values the verifier checks.
    /// The round-shape checks inside [`Self::verify_rounds`] are what bind the
    /// claim, and they apply unchanged to the extra randomization round.
    fn verify_with_preprocessing(
        &self,
        rounds: Vec<CommitmentOpening<EF, Self::Commitment, Self::Domain>>,
        proof: &Self::Proof,
        challenger: &mut Challenger,
        _preprocessed_commitment: Option<usize>,
    ) -> Result<(), Self::Error> {
        let plain = rounds
            .into_iter()
            .map(|claim| {
                (
                    claim.commitment,
                    claim
                        .matrices
                        .into_iter()
                        .map(|matrix| {
                            (
                                matrix.domain,
                                matrix
                                    .points
                                    .into_iter()
                                    .map(|point| (point.point, point.values))
                                    .collect(),
                            )
                        })
                        .collect(),
                )
            })
            .collect();
        self.verify_rounds(plain, proof, challenger)
    }
}

impl<EF, F, Dft, MT, Challenger, L> WhirUniPcs<EF, F, Dft, MT, Challenger, L>
where
    F: TwoAdicField + PrimeField64 + Ord,
    EF: ExtensionField<F> + TwoAdicField,
    MT: Mmcs<F>,
    Challenger: FieldChallenger<F>
        + GrindingChallenger<Witness = F>
        + CanSampleUniformBits<F>
        + CanObserve<MT::Commitment>
        + Clone,
{
    /// Rejects a mask too small to hide against the openings it will face.
    ///
    /// A mask of height `mask_height` carries `mask_height - 1` degrees of
    /// freedom; each opening point over a `DIMENSION`-wide extension-field
    /// value costs `DIMENSION` of them. The factor of two is margin, matching
    /// the sizing used for hiding FRI.
    fn check_hiding_budget(
        &self,
        random_cells: usize,
        points: usize,
        query_margin: usize,
        arity: usize,
        context: alloc::string::String,
    ) -> Result<(), WhirUniProverError> {
        let required = EF::DIMENSION
            .checked_mul(points.max(1))
            .and_then(|v| v.checked_add(query_margin))
            .and_then(|v| v.checked_mul(2))
            .ok_or(WhirUniProverError::BudgetOverflow)?;
        let available = random_cells;
        if required > available {
            return Err(WhirUniProverError::HidingBudgetExceeded {
                mask_height: random_cells,
                width: 1,
                arity,
                points,
                extension_degree: EF::DIMENSION,
                required,
                available,
                context,
            });
        }
        Ok(())
    }

    /// Stacked arity a commitment over these matrices will be checked at.
    ///
    /// The hiding budget depends on how many queries WHIR will make, which is a
    /// function of the stacked arity rather than of any single matrix.
    /// `extra_log_height` accounts for growth that happens after this is read,
    /// such as the mask widening the committed matrix.
    fn stacked_arity_of(&self, mats: &[RowMajorMatrix<F>], extra_log_height: usize) -> usize {
        let shapes = mats.iter().map(|m| {
            let log_h = log2_strict_usize(m.height()) + extra_log_height;
            (padded_arity(log_h, self.folding), m.width())
        });
        checked_stacked_num_variables(shapes).unwrap_or(self.log_max_lde_height)
    }

    /// Margin term for the hiding budget: the protocol's query cost at a given
    /// stacked arity.
    ///
    /// Every query WHIR makes against a committed codeword is one more linear
    /// constraint on the mask, so the mask's random subspace has to dominate
    /// the total query count. The query count is a function of the stacked
    /// arity, so it is read off the schedule for the arity actually being
    /// committed rather than the instance cap.
    ///
    /// Falls back to the security level if no schedule builds at that arity,
    /// which makes the check conservative rather than absent.
    pub fn query_margin(&self, stacked_num_variables: usize) -> usize {
        WhirConfig::<EF, F, Challenger>::new(stacked_num_variables, self.protocol_params.clone())
            .map(|config| {
                config
                    .round_parameters()
                    .iter()
                    .map(|round| round.num_queries)
                    .sum::<usize>()
                    + config.terminal().num_queries
            })
            .unwrap_or(self.protocol_params.security_level)
    }
}

/// Renders a batch's matrix shapes, for hiding-budget diagnostics.
fn batch_shapes(mats: &[RowMajorMatrix<impl Field>]) -> alloc::string::String {
    mats.iter()
        .map(|m| alloc::format!("{}x{}", m.height(), m.width()))
        .collect::<alloc::vec::Vec<_>>()
        .join(" ")
}

/// Renders domain sizes, for the randomization-commitment diagnostic.
fn domain_shapes(sizes: &[usize]) -> alloc::string::String {
    sizes
        .iter()
        .map(|s| alloc::format!("{s}"))
        .collect::<alloc::vec::Vec<_>>()
        .join(" ")
}

/// Lagrange normalization constants for the quotient chunk domains.
///
/// `cis[i] = 1 / prod_{j != i} Z_{D_j}(first_i)`, the constant that turns the
/// chunk selector into a multiple of the product of all vanishing
/// polynomials. Section 4.2 of <https://eprint.iacr.org/2024/1037.pdf>.
fn zp_cis<D: PolynomialSpace>(domains: &[D]) -> Vec<D::Val> {
    batch_multiplicative_inverse(
        &domains
            .iter()
            .enumerate()
            .map(|(i, domain)| {
                domains
                    .iter()
                    .enumerate()
                    .filter(|(j, _)| *j != i)
                    .map(|(_, other)| other.vanishing_poly_at_point(domain.first_point()))
                    .product()
            })
            .collect::<Vec<_>>(),
    )
}

#[cfg(test)]
pub(crate) mod tests {
    extern crate std;
    use alloc::vec;
    use alloc::vec::Vec;
    use core::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::Arc;

    use p3_baby_bear::{BabyBear, Poseidon2BabyBear};
    use p3_challenger::DuplexChallenger;
    use p3_commit::PolynomialSpace;
    use p3_dft::{Radix2DFTSmallBatch, TwoAdicSubgroupDft};
    use p3_field::coset::TwoAdicMultiplicativeCoset;
    use p3_field::extension::BinomialExtensionField;
    use p3_field::{Field, PrimeCharacteristicRing};
    use p3_matrix::Matrix;
    use p3_matrix::dense::RowMajorMatrix;
    use p3_merkle_tree::MerkleTreeMmcs;
    use p3_sumcheck::layout::PrefixProver;
    use p3_symmetric::{PaddingFreeSponge, TruncatedPermutation};
    use p3_whir::parameters::{FoldingFactor, ProtocolParameters, SecurityAssumption};
    use rand::SeedableRng;
    use rand::rngs::SmallRng;

    use super::WhirUniPcs;

    type F = BabyBear;
    type EF = BinomialExtensionField<F, 4>;
    type Perm = Poseidon2BabyBear<16>;
    type MyHash = PaddingFreeSponge<Perm, 16, 8, 8>;
    type MyCompress = TruncatedPermutation<Perm, 2, 8, 16>;
    type PackedF = <F as Field>::Packing;
    pub(crate) type MyMmcs = MerkleTreeMmcs<PackedF, PackedF, MyHash, MyCompress, 2, 8>;
    type MyDft = Radix2DFTSmallBatch<F>;
    pub(crate) type MyChallenger = DuplexChallenger<F, Perm, 16, 8>;
    pub(crate) type MyPcs = WhirUniPcs<EF, F, MyDft, MyMmcs, MyChallenger, PrefixProver<F, EF>>;

    #[derive(Clone)]
    struct CountingChallenger<C> {
        inner: C,
        calls: Arc<AtomicUsize>,
    }

    impl<C> CountingChallenger<C> {
        fn new(inner: C, calls: Arc<AtomicUsize>) -> Self {
            Self { inner, calls }
        }

        fn count(&self) {
            self.calls.fetch_add(1, Ordering::SeqCst);
        }
    }

    impl<C, T> p3_challenger::CanObserve<T> for CountingChallenger<C>
    where
        C: p3_challenger::CanObserve<T>,
    {
        fn observe(&mut self, value: T) {
            self.count();
            self.inner.observe(value);
        }
    }

    impl<C, T> p3_challenger::CanSample<T> for CountingChallenger<C>
    where
        C: p3_challenger::CanSample<T>,
    {
        fn sample(&mut self) -> T {
            self.count();
            self.inner.sample()
        }
    }

    impl<C, T> p3_challenger::CanSampleBits<T> for CountingChallenger<C>
    where
        C: p3_challenger::CanSampleBits<T>,
    {
        fn sample_bits(&mut self, bits: usize) -> T {
            self.count();
            self.inner.sample_bits(bits)
        }
    }

    impl<C> p3_challenger::CanSampleUniformBits<F> for CountingChallenger<C>
    where
        C: p3_challenger::CanSampleUniformBits<F>,
    {
        fn sample_uniform_bits<const RESAMPLE: bool>(
            &mut self,
            bits: usize,
        ) -> Result<usize, p3_challenger::ResamplingError> {
            self.count();
            self.inner.sample_uniform_bits::<RESAMPLE>(bits)
        }
    }

    impl<C> p3_challenger::GrindingChallenger for CountingChallenger<C>
    where
        C: p3_challenger::GrindingChallenger<Witness = F>,
    {
        type Witness = F;

        fn grind(&mut self, bits: usize) -> Self::Witness {
            self.count();
            self.inner.grind(bits)
        }
    }

    impl<C> p3_challenger::FieldChallenger<F> for CountingChallenger<C> where
        C: p3_challenger::FieldChallenger<F>
    {
    }

    type CountingPcs =
        WhirUniPcs<EF, F, MyDft, MyMmcs, CountingChallenger<MyChallenger>, PrefixProver<F, EF>>;
    type CountingConfig =
        p3_uni_stark::StarkConfig<CountingPcs, EF, CountingChallenger<MyChallenger>>;

    fn counting_pcs(base: &MyPcs, calls: Arc<AtomicUsize>) -> CountingPcs {
        WhirUniPcs::new(
            base.protocol_params.clone(),
            base.dft.clone(),
            base.mmcs.clone(),
            CountingChallenger::new(base.challenger_proto.clone(), calls),
            base.log_max_lde_height,
        )
    }

    pub(super) fn test_pcs() -> MyPcs {
        let mut rng = SmallRng::seed_from_u64(1);
        let perm = Perm::new_from_rng_128(&mut rng);
        let hash = MyHash::new(perm.clone());
        let compress = MyCompress::new(perm.clone());
        let params = ProtocolParameters {
            security_level: 32,
            pow_bits: 0,
            round_log_inv_rates: vec![],
            folding_factor: FoldingFactor::Constant(4),
            soundness_type: SecurityAssumption::CapacityBound,
            starting_log_inv_rate: 1,
        };
        WhirUniPcs::new(
            params,
            MyDft::default(),
            MyMmcs::new(hash, compress, 0),
            MyChallenger::new(perm),
            20,
        )
    }

    #[test]
    fn folding_is_read_from_the_protocol_parameters() {
        assert_eq!(test_pcs().folding(), 4);
    }

    /// The stacked arity a commitment reports must be what the layout planner
    /// says for the padded table shapes, and the WHIR config must be built for
    /// exactly that arity.
    ///
    /// Under zero knowledge the committed polynomial is the *masked* one: each
    /// matrix is interleaved with a random companion, doubling its height, so
    /// the domain handed to `commit` must already be the doubled domain — which
    /// is exactly what the STARK prover passes. The original evaluations
    /// survive in the even rows of the committed codeword.
    #[test]
    fn commit_plans_the_stacked_layout_and_stores_coefficients() {
        let pcs = test_pcs();
        let dft = MyDft::default();
        let mut rng = SmallRng::seed_from_u64(3);

        // Two matrices: 2^6 x 3 and 2^5 x 2, committed on the doubled cosets.
        let d0 = TwoAdicMultiplicativeCoset::<F>::new(F::ONE, 7).unwrap();
        let d1 = TwoAdicMultiplicativeCoset::<F>::new(F::GENERATOR, 6).unwrap();
        let m0 = RowMajorMatrix::<F>::rand(&mut rng, 1 << 6, 3);
        let m1 = RowMajorMatrix::<F>::rand(&mut rng, 1 << 5, 2);

        let (_commit, data) = <MyPcs as p3_commit::Pcs<EF, MyChallenger>>::commit(
            &pcs,
            vec![(d0, m0.clone()), (d1, m1.clone())],
        )
        .unwrap();

        // Masked: 3 * 2^7 + 2 * 2^6 = 512 -> stacked arity 9.
        assert_eq!(data.stacked_num_variables, 9);
        assert_eq!(data.plan.num_variables, 9);
        // Largest table first.
        assert_eq!(data.plan.placements[0].table_idx, 0);
        assert_eq!(data.plan.placements[1].table_idx, 1);

        // The stored coefficients interpolate to the masked codeword, whose
        // even rows are the original evaluations and whose odd rows are the
        // mask. Asserting the even-row recovery is the strongest statement that
        // survives blinding: the witness is preserved, the extra rows are not
        // predictable.
        let back0 = dft
            .coset_dft_batch(data.coeffs[0].clone(), d0.shift())
            .to_row_major_matrix();
        assert_eq!(back0.height(), 1 << 7);
        let w0 = m0.width();
        for row in 0..(1 << 6) {
            assert_eq!(
                back0.values[(row * 2) * w0..(row * 2 + 1) * w0],
                m0.values[row * w0..(row + 1) * w0],
                "matrix 0 row {row} must survive in the even row"
            );
        }
        let back1 = dft
            .coset_dft_batch(data.coeffs[1].clone(), d1.shift())
            .to_row_major_matrix();
        assert_eq!(back1.height(), 1 << 6);
        let w1 = m1.width();
        for row in 0..(1 << 5) {
            assert_eq!(
                back1.values[(row * 2) * w1..(row * 2 + 1) * w1],
                m1.values[row * w1..(row + 1) * w1],
                "matrix 1 row {row} must survive in the even row"
            );
        }
    }

    #[test]
    fn natural_domain_has_the_requested_size() {
        let pcs = test_pcs();
        let d =
            <MyPcs as p3_commit::Pcs<EF, MyChallenger>>::natural_domain_for_degree(&pcs, 1 << 7);
        assert_eq!(d.size(), 1 << 7);
        assert_eq!(d.shift(), F::ONE);
    }

    /// Evaluations returned for a larger, shifted domain must equal a direct
    /// coset LDE of the stored coefficients.
    ///
    /// The stored coefficients are the *masked* polynomial's, so the LDE is of
    /// the masked polynomial; the test's reference reads them off the prover
    /// data rather than the original witness, which is the only thing that can
    /// be checked once blinding is on.
    #[test]
    fn evaluations_on_domain_matches_a_direct_coset_lde() {
        let pcs = test_pcs();
        let dft = MyDft::default();
        let mut rng = SmallRng::seed_from_u64(5);

        // The witness is 2^9 x 4 rows; the commit domain is the doubled one
        // the STARK prover hands over. The size is not arbitrary: a masked
        // commitment must carry at least `2 * (e * n_F + n_D)` random field
        // elements, so a toy-sized matrix cannot be hidden at all.
        let trace_domain = TwoAdicMultiplicativeCoset::<F>::new(F::ONE, 10).unwrap();
        let mat = RowMajorMatrix::<F>::rand(&mut rng, 1 << 9, 4);
        let (_c, data) =
            <MyPcs as p3_commit::Pcs<EF, MyChallenger>>::commit(&pcs, vec![(trace_domain, mat)])
                .unwrap();

        // Quotient domain: 2x larger, disjoint coset.
        let quotient_domain = trace_domain.create_disjoint_domain(1 << 11);
        let got =
            <MyPcs as p3_commit::UnivariateStarkPcs<EF, MyChallenger>>::get_evaluations_on_domain(
                &pcs,
                &data,
                0,
                quotient_domain,
            );

        // Reference: pad the coefficients to the quotient height, then coset-DFT.
        let mut coeffs = data.coeffs[0].clone();
        let width = coeffs.width();
        coeffs
            .values
            .resize(quotient_domain.size() * width, F::ZERO);
        let want = dft
            .coset_dft_batch(
                RowMajorMatrix::new(coeffs.values, width),
                quotient_domain.shift(),
            )
            .to_row_major_matrix();

        assert_eq!(got.height(), quotient_domain.size());
        assert_eq!(got.values, want.values);
    }

    /// Asking for the committed domain itself must return the masked codeword,
    /// whose even rows are the original evaluations.
    #[test]
    fn evaluations_on_the_committed_domain_round_trip() {
        let pcs = test_pcs();
        let mut rng = SmallRng::seed_from_u64(6);
        let domain = TwoAdicMultiplicativeCoset::<F>::new(F::GENERATOR, 10).unwrap();
        let mat = RowMajorMatrix::<F>::rand(&mut rng, 1 << 9, 4);
        let (_c, data) =
            <MyPcs as p3_commit::Pcs<EF, MyChallenger>>::commit(&pcs, vec![(domain, mat.clone())])
                .unwrap();

        let got =
            <MyPcs as p3_commit::UnivariateStarkPcs<EF, MyChallenger>>::get_evaluations_on_domain(
                &pcs, &data, 0, domain,
            );
        assert_eq!(got.height(), 1 << 10);
        let w = mat.width();
        for row in 0..(1 << 9) {
            assert_eq!(
                got.values[(row * 2) * w..(row * 2 + 1) * w],
                mat.values[row * w..(row + 1) * w],
                "row {row} must survive in the even row of the committed codeword"
            );
        }
    }

    /// A quotient commitment stores each chunk's *masked* polynomial
    /// `q_i + Z_{D_i} * T_i`. The mask vanishes on the chunk's own coset, so
    /// evaluating the stored coefficients at the chunk's domain points must
    /// reproduce the original chunk evaluations exactly — the witness is
    /// preserved where the verifier looks, and is free everywhere else.
    #[test]
    fn quotient_chunks_are_committed_as_chunk_coefficients() {
        let pcs = test_pcs();
        let mut rng = SmallRng::seed_from_u64(13);

        let quotient_domain = TwoAdicMultiplicativeCoset::<F>::new(F::GENERATOR, 6).unwrap();
        let evals = RowMajorMatrix::<F>::rand(&mut rng, 1 << 6, 1);
        let num_chunks = 4;

        let (_c, data) =
            <MyPcs as p3_commit::UnivariateStarkPcs<EF, MyChallenger>>::commit_quotient(
                &pcs,
                quotient_domain,
                evals.clone(),
                num_chunks,
            )
            .unwrap();

        let sub_domains = quotient_domain.split_domains(num_chunks);
        let sub_evals = quotient_domain.split_evals(num_chunks, evals);
        assert_eq!(data.coeffs.len(), num_chunks);
        for (i, (sd, se)) in sub_domains.iter().zip(sub_evals).enumerate() {
            let coeffs = &data.coeffs[i];
            // The mask term has degree < 2h, so the stored chunk is twice the
            // chunk domain's height.
            assert_eq!(coeffs.height(), 2 * sd.size(), "chunk {i} height");
            // Horner-evaluate the masked chunk at the chunk's own points.
            let g = sd.subgroup_generator();
            let mut x = sd.first_point();
            for row in 0..sd.size() {
                let xf = EF::from(x);
                let want = EF::from(se.get(row, 0).expect("chunk row in range"));
                let got = (0..coeffs.height())
                    .rev()
                    .fold(EF::ZERO, |acc, k| acc * xf + EF::from(coeffs.values[k]));
                assert_eq!(
                    got, want,
                    "chunk {i} point {row}: mask must vanish on its own coset"
                );
                x *= g;
            }
        }

        // The recorded domains are unit-shift height-only placeholders, one
        // per chunk: real chunk height, but not the chunk's actual shift.
        assert_eq!(data.domains.len(), num_chunks);
        for (i, domain) in data.domains.iter().enumerate() {
            assert_eq!(domain.shift(), F::ONE, "chunk {i}");
            assert_eq!(domain.size(), data.coeffs[i].height(), "chunk {i}");
        }

        // 4 chunks x 2^5 masked rows x 1 column = 128 -> stacked arity 7.
        assert_eq!(data.stacked_num_variables, 7);
    }

    /// The schedule must place one opening batch per point per matrix, in
    /// matrix-then-point order, with points padded to the folding depth.
    #[test]
    fn round_schedule_lists_one_batch_per_point() {
        use super::round_schedule;

        let z0 = EF::from_u32(11);
        let z1 = EF::from_u32(13);
        // Matrix 0: 2^6 rows, 3 cols, opened at z0 and z1. Matrix 1: 2^2 rows,
        // 2 cols (below the folding depth of 4), opened at z0 only.
        let schedule = round_schedule::<F, EF>(&[(6, 3), (2, 2)], &[vec![z0, z1], vec![z0]], 4);

        assert_eq!(schedule.protocol.num_openings(), 3);
        assert_eq!(schedule.points.len(), 3);
        assert_eq!(schedule.points[0].num_variables(), 6);
        assert_eq!(schedule.points[1].num_variables(), 6);
        // Matrix 1 is padded from arity 2 up to the folding depth 4.
        assert_eq!(schedule.points[2].num_variables(), 4);
        assert_eq!(schedule.scales.len(), 2);
        assert_eq!(schedule.scales[0].len(), 2);
        assert_eq!(schedule.scales[1].len(), 1);
    }

    /// `open` must report the true univariate evaluations of the *masked*
    /// polynomial, and the WHIR argument's own multilinear values must
    /// rescale to exactly those.
    #[test]
    fn open_reports_univariate_evaluations_consistent_with_the_whir_claim() {
        let pcs = test_pcs();
        let mut rng = SmallRng::seed_from_u64(21);

        // 2^6 witness rows committed on the doubled 2^7 coset.
        let domain = TwoAdicMultiplicativeCoset::<F>::new(F::ONE, 7).unwrap();
        let mat = RowMajorMatrix::<F>::rand(&mut rng, 1 << 6, 2);
        let (_c, data) =
            <MyPcs as p3_commit::Pcs<EF, MyChallenger>>::commit(&pcs, vec![(domain, mat)]).unwrap();

        let zeta = EF::from_u32(9_999);
        let mut challenger = pcs.challenger_proto.clone();
        let (opened, proof) = <MyPcs as p3_commit::Pcs<EF, MyChallenger>>::open(
            &pcs,
            vec![(&data, vec![vec![zeta]]).into()],
            &mut challenger,
        )
        .unwrap();

        // Reference: Horner over the stored (masked) coefficients.
        let coeffs = &data.coeffs[0];
        for (col, &got) in opened[0][0][0].iter().enumerate() {
            let want = (0..coeffs.height()).rev().fold(EF::ZERO, |acc, i| {
                acc * zeta + coeffs.values[i * coeffs.width() + col]
            });
            assert_eq!(got, want, "column {col}");
        }

        // The WHIR argument bound the rescaled multilinear values.
        let schedule = super::round_schedule::<F, EF>(&[(7, 2)], &[vec![zeta]], pcs.folding());
        let batch = &proof.rounds[0].evals[0];
        for (col, &want) in opened[0][0][0].iter().enumerate() {
            assert_eq!(batch.current()[col] * schedule.scales[0][0], want);
        }
    }

    /// Builds an honest commit/open pair over two matrices at two points and
    /// returns everything `verify` needs.
    #[allow(clippy::type_complexity)]
    pub(crate) fn open_two_matrices() -> (
        MyPcs,
        <MyMmcs as p3_commit::Mmcs<F>>::Commitment,
        Vec<(TwoAdicMultiplicativeCoset<F>, Vec<(EF, Vec<EF>)>)>,
        super::WhirUniProof<F, EF, MyMmcs>,
    ) {
        let pcs = test_pcs();
        let mut rng = SmallRng::seed_from_u64(31);
        // Witness rows are 2^6 and 2^5; the commit path interleaves a random
        // companion row per witness row, so the domains are the doubled ones.
        let d0 = TwoAdicMultiplicativeCoset::<F>::new(F::ONE, 7).unwrap();
        let d1 = TwoAdicMultiplicativeCoset::<F>::new(F::ONE, 6).unwrap();
        let m0 = RowMajorMatrix::<F>::rand(&mut rng, 1 << 6, 2);
        let m1 = RowMajorMatrix::<F>::rand(&mut rng, 1 << 5, 1);
        let (commit, data) =
            <MyPcs as p3_commit::Pcs<EF, MyChallenger>>::commit(&pcs, vec![(d0, m0), (d1, m1)])
                .unwrap();

        let zeta = EF::from_u32(777);
        let zeta_next = zeta * EF::from(d0.subgroup_generator());
        let points = vec![vec![zeta, zeta_next], vec![zeta]];

        let mut challenger = pcs.challenger_proto.clone();
        let (opened, proof) = <MyPcs as p3_commit::Pcs<EF, MyChallenger>>::open(
            &pcs,
            vec![(&data, points).into()],
            &mut challenger,
        )
        .unwrap();

        let coms = vec![
            (
                d0,
                vec![
                    (zeta, opened[0][0][0].clone()),
                    (zeta_next, opened[0][0][1].clone()),
                ],
            ),
            (d1, vec![(zeta, opened[0][1][0].clone())]),
        ];
        (pcs, commit, coms, proof)
    }

    #[test]
    fn verify_accepts_an_honest_opening() {
        let (pcs, commit, coms, proof) = open_two_matrices();
        let mut challenger = pcs.challenger_proto.clone();
        <MyPcs as p3_commit::Pcs<EF, MyChallenger>>::verify(
            &pcs,
            vec![(commit, coms).into()],
            &proof,
            &mut challenger,
        )
        .expect("honest opening verifies");
    }

    #[test]
    fn verify_rejects_a_malformed_last_argument_before_any_challenger_use() {
        let (base_pcs, commitment, matrices, proof) = open_two_matrices();
        let mut malformed_last = proof.rounds[0].clone();
        match &mut malformed_last.whir.final_openings {
            p3_whir::pcs::proof::QueryOpenings::Base(opening) => {
                opening.rows.last_mut().unwrap().pop();
            }
            p3_whir::pcs::proof::QueryOpenings::Extension(opening) => {
                opening.rows.last_mut().unwrap().pop();
            }
        }
        let two_round_proof = super::WhirUniProof {
            rounds: vec![proof.rounds[0].clone(), malformed_last],
        };
        let commitments = vec![
            (commitment.clone(), matrices.clone()).into(),
            (commitment, matrices).into(),
        ];
        let calls = Arc::new(AtomicUsize::new(0));
        let mut challenger =
            CountingChallenger::new(base_pcs.challenger_proto.clone(), Arc::clone(&calls));
        let pcs = counting_pcs(&base_pcs, Arc::clone(&calls));

        let error = <_ as p3_commit::Pcs<EF, CountingChallenger<MyChallenger>>>::verify(
            &pcs,
            commitments,
            &two_round_proof,
            &mut challenger,
        )
        .expect_err("the malformed last WHIR argument must reject");

        assert!(matches!(
            error,
            super::WhirUniPcsError::ShapeMismatch { round: 1 }
        ));
        assert_eq!(
            calls.load(Ordering::SeqCst),
            0,
            "native verify_rounds must finish the whole structural pass before challenger work"
        );
    }

    #[test]
    fn direct_replay_and_restoration_preflight_the_malformed_last_argument() {
        let (base_pcs, commitment, matrices, proof) = open_two_matrices();
        let calls = Arc::new(AtomicUsize::new(0));
        let counting = counting_pcs(&base_pcs, Arc::clone(&calls));
        let honest_transcript = crate::generation::OpeningTranscript::<CountingConfig> {
            challenger: CountingChallenger::new(
                base_pcs.challenger_proto.clone(),
                Arc::clone(&calls),
            ),
            commitments_with_opening_points: vec![(commitment.clone(), matrices.clone())],
        };
        let (honest, positive) = crate::pcs::whir::uni::acceptance_probe::measure(|| {
            crate::pcs::whir::uni::restore_whir_recursion_paths::<
                CountingConfig,
                PackedF,
                PackedF,
                MyHash,
                MyCompress,
                2,
                8,
            >(
                &counting.mmcs,
                honest_transcript,
                &proof,
                &counting.protocol_params,
                counting.folding(),
                p3_sumcheck::strategy::VariableOrder::Prefix,
            )
        });
        honest.expect("the genuine WHIR proof replays and restores its paths");
        assert_eq!(positive.query_replay, 1);
        assert_eq!(positive.restoration, 1);
        assert!(
            calls.load(Ordering::SeqCst) > 0,
            "the positive replay must exercise the wrapped challenger"
        );

        calls.store(0, Ordering::SeqCst);
        let mut malformed_last = proof.rounds[0].clone();
        match &mut malformed_last.whir.final_openings {
            p3_whir::pcs::proof::QueryOpenings::Base(opening) => {
                opening.rows.last_mut().unwrap().pop();
            }
            p3_whir::pcs::proof::QueryOpenings::Extension(opening) => {
                opening.rows.last_mut().unwrap().pop();
            }
        }
        let malformed_proof = super::WhirUniProof {
            rounds: vec![proof.rounds[0].clone(), malformed_last],
        };
        let malformed_transcript = crate::generation::OpeningTranscript::<CountingConfig> {
            challenger: CountingChallenger::new(base_pcs.challenger_proto, Arc::clone(&calls)),
            commitments_with_opening_points: vec![
                (commitment.clone(), matrices.clone()),
                (commitment, matrices),
            ],
        };
        let (malformed, negative) = crate::pcs::whir::uni::acceptance_probe::measure(|| {
            crate::pcs::whir::uni::restore_whir_recursion_paths::<
                CountingConfig,
                PackedF,
                PackedF,
                MyHash,
                MyCompress,
                2,
                8,
            >(
                &counting.mmcs,
                malformed_transcript,
                &malformed_proof,
                &counting.protocol_params,
                counting.folding(),
                p3_sumcheck::strategy::VariableOrder::Prefix,
            )
        });
        assert!(malformed.is_err());
        assert_eq!(calls.load(Ordering::SeqCst), 0);
        assert_eq!(negative.query_replay, 0);
        assert_eq!(negative.restoration, 0);
    }

    #[test]
    fn verify_rejects_a_tampered_opened_value() {
        let (pcs, commit, mut coms, proof) = open_two_matrices();
        coms[0].1[0].1[0] += EF::ONE;
        let mut challenger = pcs.challenger_proto.clone();
        let err = <MyPcs as p3_commit::Pcs<EF, MyChallenger>>::verify(
            &pcs,
            vec![(commit, coms).into()],
            &proof,
            &mut challenger,
        )
        .expect_err("a tampered opened value must be rejected");
        assert!(
            matches!(
                err,
                super::WhirUniPcsError::OpeningValueMismatch {
                    round: 0,
                    batch: 0,
                    column: 0,
                }
            ),
            "expected an OpeningValueMismatch at round 0, batch 0, column 0, got {err:?}"
        );
    }

    #[test]
    fn verify_rejects_a_tampered_final_polynomial() {
        let (pcs, commit, coms, mut proof) = open_two_matrices();
        let poly = proof.rounds[0]
            .whir
            .final_poly
            .as_mut()
            .expect("final poly");
        poly.as_mut_slice()[0] += EF::ONE;
        let mut challenger = pcs.challenger_proto.clone();
        let err = <MyPcs as p3_commit::Pcs<EF, MyChallenger>>::verify(
            &pcs,
            vec![(commit, coms).into()],
            &proof,
            &mut challenger,
        )
        .expect_err("a tampered final polynomial must be rejected");
        assert!(
            matches!(err, super::WhirUniPcsError::Whir { round: 0, .. }),
            "expected a Whir error at round 0, got {err:?}"
        );
    }
}
